#!/usr/bin/env python3
"""Generate the README banner and the GitHub social card.

The look is an amber CRT terminal - the thing you'd have been staring at if you
were reading a serial console thirty years ago. The waveform running under the
wordmark is a real 8N1 encoding of "HERMES" at 115200, generated by the same
bit-packing the firmware decodes.
"""

from PIL import Image, ImageDraw, ImageFont
import os

OUT = os.path.join(os.path.dirname(__file__), "images")
os.makedirs(OUT, exist_ok=True)

BG = (10, 9, 8)
PANEL = (18, 16, 13)
AMBER = (255, 176, 46)
AMBER_DIM = (146, 98, 24)
AMBER_FAINT = (58, 40, 12)
WHITE = (245, 240, 232)
GREY = (138, 130, 118)

FB = "/System/Library/Fonts/Supplemental/Arial Bold.ttf"
FBLK = "/System/Library/Fonts/Supplemental/Arial Black.ttf"
FR = "/System/Library/Fonts/Supplemental/Arial.ttf"
FMONO = "/System/Library/Fonts/Menlo.ttc"


def f(path, px):
    return ImageFont.truetype(path, px)


# ------------------------------------------------------------------ parts ----


def scanlines(img, step=3, alpha=54):
    """Every third row dimmed - the CRT tell.

    Composited at low alpha rather than drawn as solid black lines: at full
    strength it stripes the wordmark and the whole thing stops being readable.
    """
    overlay = Image.new("RGBA", img.size, (0, 0, 0, 0))
    od = ImageDraw.Draw(overlay)
    for y in range(0, img.size[1], step):
        od.line([(0, y), (img.size[0], y)], fill=(0, 0, 0, alpha))
    return Image.alpha_composite(img.convert("RGBA"), overlay).convert("RGB")


def callout(d, right, baseline, num, framing, sub):
    """The answer, in a box sized to its contents.

    Measured rather than guessed - hardcoding the width is how "115200" ends up
    printed through "8N1".
    """
    f_num, f_fr, f_sub = f(FBLK, 46), f(FB, 26), f(FMONO, 12)
    nw = d.textlength(num, font=f_num)
    rw = d.textlength(framing, font=f_fr)

    pad, gap = 20, 16
    box_w = pad + nw + gap + rw + pad
    box_h = 84
    x0 = right - box_w
    y0 = baseline - box_h

    d.rounded_rectangle(
        [x0, y0, x0 + box_w, y0 + box_h], radius=10, outline=AMBER_DIM, width=2
    )
    d.text((x0 + pad, y0 + 52), num, font=f_num, fill=AMBER, anchor="ls")
    d.text((x0 + pad + nw + gap, y0 + 52), framing, font=f_fr, fill=WHITE, anchor="ls")
    d.text((x0 + pad, y0 + 72), sub, font=f_sub, fill=GREY, anchor="ls")
    return x0


def uart_bits(text):
    """8N1 framing: start low, eight data bits LSB first, stop high."""
    bits = []
    for ch in text:
        bits.append(0)
        bits += [(ord(ch) >> i) & 1 for i in range(8)]
        bits.append(1)
        bits.append(1)  # a beat of idle between frames
    return bits


def draw_wave(d, bits, x0, y_hi, y_lo, bit_px, colour, width=3, x_max=None):
    """Square wave, drawn the way the app's scope draws it."""
    x = x0
    prev = None
    for b in bits:
        if x_max and x > x_max:
            break
        y = y_hi if b else y_lo
        d.line([(x, y), (x + bit_px, y)], fill=colour, width=width)
        if prev is not None and prev != b:
            d.line([(x, y_hi), (x, y_lo)], fill=colour, width=width)
        prev = b
        x += bit_px
    return x


def chip(d, x, y, label, font, fg, bd):
    """Small outlined pill, for the feature row."""
    tw = d.textlength(label, font=font)
    d.rounded_rectangle([x, y, x + tw + 22, y + 30], radius=15, outline=bd, width=2)
    d.text((x + 11, y + 15), label, font=font, fill=fg, anchor="lm")
    return x + tw + 22


# ----------------------------------------------------------------- banner ----


def banner(w=1280, h=420, name="banner.png"):
    img = Image.new("RGB", (w, h), BG)
    d = ImageDraw.Draw(img)

    # a soft amber wash behind the wordmark
    for i in range(60):
        t = i / 60
        d.rectangle(
            [0, int(h * 0.18) + i * 3, w, int(h * 0.18) + i * 3 + 3],
            fill=(
                int(BG[0] + (PANEL[0] - BG[0]) * (1 - t)),
                int(BG[1] + (PANEL[1] - BG[1]) * (1 - t)),
                int(BG[2] + (PANEL[2] - BG[2]) * (1 - t)),
            ),
        )

    # the wire, running the full width behind everything
    draw_wave(d, uart_bits("HERMES"), -20, 96, 128, 9, AMBER_FAINT, width=3, x_max=w)

    d.text((64, 152), "HERMES", font=f(FBLK, 92), fill=AMBER, anchor="ls")
    d.text(
        (68, 190),
        "Every wire is talking.  Hermes tells you what it's saying.",
        font=f(FR, 25),
        fill=WHITE,
        anchor="ls",
    )

    # the answer, boxed on the right; the trace runs up to it
    box_x = callout(d, w - 64, 296, "115200", "8N1", "verified on the wire")

    end = draw_wave(
        d, uart_bits("root@"), 64, 232, 276, 11, AMBER, width=3, x_max=box_x - 48
    )
    d.line([(64, 300), (end, 300)], fill=AMBER_FAINT, width=1)
    d.text((64, 322), "measured on the pin", font=f(FMONO, 14), fill=GREY, anchor="ls")

    x = 64
    for label in (
        "Auto-baud",
        "Framing detect",
        "Live console",
        "Read-only by default",
    ):
        x = chip(d, x, 354, label, f(FB, 15), AMBER, AMBER_DIM) + 12

    d.text(
        (w - 64, 376),
        "FLIPPER ZERO  ·  GPIO",
        font=f(FB, 15),
        fill=AMBER_DIM,
        anchor="rs",
    )

    img = scanlines(img)
    path = os.path.join(OUT, name)
    img.save(path)
    print("wrote", path)


# ---------------------------------------------------------- social preview ---


def social(w=1280, h=640, name="social-preview.png"):
    img = Image.new("RGB", (w, h), BG)
    d = ImageDraw.Draw(img)

    # Long enough to run the full width; the lower one stops short of the box.
    draw_wave(
        d, uart_bits("HERMES HERMES"), -20, 150, 190, 11, AMBER_FAINT, width=3, x_max=w
    )
    draw_wave(
        d, uart_bits("UART UART"), -60, 470, 510, 13, AMBER_FAINT, width=3, x_max=470
    )

    d.text((w // 2, 300), "HERMES", font=f(FBLK, 128), fill=AMBER, anchor="ms")
    d.text(
        (w // 2, 348),
        "UART baud detector  +  console tap",
        font=f(FB, 30),
        fill=WHITE,
        anchor="ms",
    )
    d.text(
        (w // 2, 390),
        "Clip on. It measures the bit time, verifies it on the UART,",
        font=f(FR, 22),
        fill=GREY,
        anchor="ms",
    )
    d.text(
        (w // 2, 420),
        "and hands you the console.",
        font=f(FR, 22),
        fill=GREY,
        anchor="ms",
    )

    # centred: size the box first, then place it about the midline
    probe = ImageDraw.Draw(Image.new("RGB", (1, 1)))
    box_w = (
        20
        + probe.textlength("115200", font=f(FBLK, 46))
        + 16
        + probe.textlength("8N1", font=f(FB, 26))
        + 20
    )
    callout(d, int(w // 2 + box_w // 2), 524, "115200", "8N1", "verified on the wire")

    d.text(
        (w // 2, 592),
        "Flipper Zero  ·  at0m-b0mb",
        font=f(FB, 20),
        fill=AMBER_DIM,
        anchor="ms",
    )

    img = scanlines(img)
    path = os.path.join(OUT, name)
    img.save(path)
    print("wrote", path)


if __name__ == "__main__":
    banner()
    social()
